export const IconWrapper: React.FC<
  IconProps & { children: React.ReactNode; viewBox?: string }
> = ({
  className = "",
  size = 24,
  color = "currentColor",
  viewBox = "0 0 350 350",
  children,
}) => {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox={viewBox}
      className={className}
      fill="none"
      style={{ color }}
    >
      {children}
    </svg>
  );
};

